# Script para instalar el sistema de pago real con Stripe:
# tabla de pedidos, funciones de servidor (Edge Functions) y los cambios
# necesarios en el checkout y la pagina de gracias.
import os

FILES_B64 = {
    "supabase/migrations/20260811000000_create_orders_table.sql": """""",
    "supabase/functions/create-checkout-session/index.ts": """""",
    "supabase/functions/stripe-webhook/index.ts": """""",
    "src/routes/checkout.tsx": """""",
    "src/routes/thanks.tsx": """""",
}

import base64
for path, b64 in FILES_B64.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'wb') as f:
        f.write(base64.b64decode(b64))
    print(f'Escrito: {path}')

# Actualizar supabase/config.toml para que apunte al proyecto nuevo
cfg_path = 'supabase/config.toml'
if os.path.exists(cfg_path):
    with open(cfg_path, 'r', encoding='utf-8') as f:
        cfg = f.read()
    old = 'project_id = "povgjedblmhjmofnbxor"'
    new = 'project_id = "gvljloichkbhtdshhklv"'
    if old in cfg:
        cfg = cfg.replace(old, new)
        with open(cfg_path, 'w', encoding='utf-8') as f:
            f.write(cfg)
        print('config.toml actualizado al proyecto nuevo')
    else:
        print('AVISO: no se encontro el project_id antiguo en config.toml, revisar a mano')

print()
print('Listo. Siguiente paso: seguir las instrucciones de despliegue que te ha dado Claude.')